<script setup lang="ts">
/**
 * An inline numbered link to a source, with a hover preview (`design/components/citation.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/citation.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */

import styles from '@polymorph/recipes/ai/citation.module.css'
import HoverCard from '../overlays/HoverCard.vue'
import type { CitationSource } from './SourceList.vue'

export interface CitationProps {
  /**
   * The mark's one-based number in the reply's SourceList.
   */
  index: number
  /**
   * The source the mark refers to, whose `href` is the link target.
   */
  source: CitationSource
}

defineOptions({ name: 'Citation', inheritAttrs: false })

defineProps<CitationProps>()
</script>

<template>
  <HoverCard>
    <template #default>
      <!-- mark -->
      <a
        :class="styles.mark"
        :href="source.href"
        target="_blank"
        rel="noreferrer"
        :aria-label="`${index}. ${source.title}`"
        data-member="citation"
      >
        {{ index }}
      </a>
    </template>
    <template #content>
      <!-- preview -->
      <span :class="styles.preview">
        <span :class="styles.previewTitle">
          {{ source.title }}
        </span>
        <span v-if="source.domain !== undefined" :class="styles.previewDomain">
          {{ source.domain }}
        </span>
        <span v-if="source.snippet !== undefined" :class="styles.previewSnippet">
          {{ source.snippet }}
        </span>
      </span>
    </template>
  </HoverCard>
</template>
